void dei_ask_notify_init( void )
{
    static const Notify_Array notify_table[] = 
    {
        { NOTIFY_PROGRAMMING_ENTER       ,	(Notify_Func)dei_ask_prg_enter	    } , 
        { NOTIFY_PROGRAMMING_LEAVE       ,	(Notify_Func)dei_ask_prg_leave     	 } , 
        { NOTIFY_REMOTE_DELETE		     ,	(Notify_Func)dei_ask_database_delete } ,
    };
    
    
    NOTIFY_ADD(notify_table);
   
}

